const D = { density:.5, energy:.6, hue:210, speed:1, scale:1, x:.5, y:.86, cover:.55, turb:.5, style:'volumetric', seed:0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const clp=(v,a,b)=>Math.max(a,Math.min(b,v));
const frc=v=>v-Math.floor(v);
const md=(a,n)=>((a%n)+n)%n;
const lrp=(a,b,t)=>a+(b-a)*t;
const fr=i=>{const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453;return s-Math.floor(s);};

const W=width,Hh=height,u=Math.min(W,Hh);
const H=md(P.hue,360);
const st=P.style;
const volumetric=st==='volumetric',sumi=st==='sumi',noir=st==='noir',thermal=st==='thermal',halftone=st==='halftone';

// fog THINS as musical intensity rises
const thin=clp(1-K.intensity*0.55,0.3,1);
const en=clp(P.energy,0,1);
const bandTop=(P.y - P.cover*0.95)*Hh;
const bandH=clp(P.cover,0.15,1)*Hh*1.15;

// t0 reset guard
if(S.lastSec==null||K.section<S.lastSec)S.lastSec=K.section;

// seeded blobs
if(S.seedUsed!==P.seed){
  S.seedUsed=P.seed; S.bl=[]; S.puffs=[];
  for(let i=0;i<48;i++){
    S.bl.push({x0:fr(i*3+1),yy:fr(i*3+2),r:0.5+fr(i*3+3),sp:0.35+fr(i*3+4)*1.3,ph:fr(i*3+5)*6.2832,up:fr(i*3+6)});
  }
}
// section-change puff injection near nozzle
if(K.section!==S.lastSec){
  S.lastSec=K.section;
  S.puffs.push({t0:K.t, x:P.x + (fr(K.section*7+1)-0.5)*0.1});
  if(S.puffs.length>4)S.puffs.shift();
}

const nB=Math.round(lrp(10,44,clp(P.density,0,1)));
const drift=0.028*P.speed*(0.75+en*0.7);
const baseA=lrp(6,17,en)*thin;
const gust=A.bass*0.5+A.lowmid*0.3;
const wobT=0.4+P.turb*1.1;
const span=W+2*u*0.35;

function fogCol(f,yy){
  if(thermal){ const h=md(H+lrp(210,-30,f),360); return [md(h,360), lrp(30,88,f), lrp(58,95,f)]; }
  if(sumi){ return [md(H,360), 5, lrp(78,34,yy)]; }
  if(noir){ return [md(H,360), 8, lrp(88,20,yy)]; }
  return [md(H+lrp(-12,14,yy),360), lrp(10,24,1-yy), lrp(62,86,1-yy)];
}

noStroke();
for(let i=0;i<nB;i++){
  const b=S.bl[i];
  const dx=frc(b.x0 + K.t*drift*b.sp + Math.sin(K.t*0.22*wobT+b.ph)*0.025);
  const bx=dx*span-u*0.35;
  const bob=Math.sin(K.t*0.5*b.sp+b.ph*1.3)*bandH*0.09*wobT;
  const by=bandTop+b.yy*bandH*0.8+bob - gust*u*0.05*b.up;
  const pulseR=1+0.16*Math.sin(K.t*0.6*P.speed+b.ph)+K.swell*0.06;
  const rr=u*(0.09+0.15*b.r)*P.scale*pulseR;
  const f=1-b.yy;
  const col=fogCol(f,b.yy);

  if(halftone){
    // dot-matrix abstraction: cluster of falloff-sized dots
    const nd=7; const gx=Math.max(2,rr/3);
    for(let d=0;d<nd;d++){
      const ang=d/nd*6.2832+b.ph;
      const rad=gx*(0.4+d*0.16);
      const px=bx+Math.cos(ang)*rad, py=by+Math.sin(ang)*rad*0.6;
      const dsz=gx*0.9*(1-d/nd)*(0.6+0.5*Math.sin(K.t*1.2+b.ph+d));
      fill(col[0],clp(col[1]+15,0,100),col[2], baseA*3.2);
      ellipse(px,py,Math.max(1.5,dsz),Math.max(1.5,dsz));
    }
    // center dot
    fill(col[0],col[1],col[2], baseA*3.5); ellipse(bx,by,gx*1.1,gx*1.1);
  } else if(noir){
    // chiaroscuro: dark mass + bright raking edge (light from left)
    fill(col[0],col[1],lrp(10,30,b.yy), baseA*1.4); ellipse(bx,by,rr*2.1,rr*1.25);
    blendMode(ADD);
    fill(md(H+8,360),12,95, baseA*0.9); ellipse(bx-rr*0.5,by-rr*0.25,rr*1.2,rr*0.7);
    blendMode(BLEND);
  } else if(sumi){
    // ink-wash tonal smoke: soft body + upward dry-brush tendril
    for(let r=0;r<3;r++){ const tt=1-r/3; fill(col[0],col[1],col[2], baseA*tt*0.9); ellipse(bx,by,rr*(1+r*0.6),rr*(0.55+r*0.28)); }
    const wsp=0.5+en*0.6;
    fill(col[0],col[1],lrp(70,40,b.yy), baseA*0.5); ellipse(bx+Math.sin(K.t*0.9+b.ph)*rr*0.4,by-rr*0.8,rr*0.35,rr*1.3*wsp);
  } else {
    // volumetric / thermal: layered translucent banks
    for(let r=0;r<3;r++){ const tt=1-r/3; fill(col[0],col[1],col[2], baseA*tt); ellipse(bx,by,rr*(1+r*0.55),rr*(0.55+r*0.3)); }
  }
}

// puffs: expanding rings from section changes
blendMode(BLEND); noStroke();
for(let p=0;p<S.puffs.length;p++){
  const pf=S.puffs[p]; const age=clp((K.t-pf.t0)*0.35*P.speed,0,1);
  if(age>=1)continue;
  const pr=u*(0.05+age*0.5)*P.scale; const pa=(1-age)*baseA*2.2;
  const px=pf.x*W + age*u*0.12; const py=bandTop+bandH*0.35;
  const c=fogCol(0.6,0.35);
  if(halftone){ for(let d=0;d<10;d++){ const a2=d/10*6.2832; fill(c[0],c[1],c[2],pa); const rr2=pr*(0.7+0.3*Math.sin(K.t*2+d)); ellipse(px+Math.cos(a2)*pr,py+Math.sin(a2)*pr*0.6,Math.max(2,rr2*0.18),Math.max(2,rr2*0.18)); } }
  else { fill(c[0],c[1],c[2],pa); ellipse(px,py,pr*2,pr*1.1); fill(c[0],c[1],clp(c[2]+10,0,100),pa*0.7); ellipse(px,py,pr*1.2,pr*0.7); }
}

blendMode(BLEND);
drawingContext.shadowBlur=0;
